{
  "50": {
    "document_id": "50",
    "label": "0",
    "explanation": "Reid's statement criticizes the Bush administration's record on global warming. Under negative clarification (3), criticism of the administration is not credit-claiming; no delivered benefit or achieved outcome is claimed."
  },
  "57": {
    "document_id": "57",
    "label": "0",
    "explanation": "Kennedy introduces stem cell/cloning legislation and argues for its merits. This matches the codebook's negative example exactly: under negative clarification (2), introducing a bill is a proposal, not an achieved outcome, so there is nothing to claim credit for."
  },
  "89": {
    "document_id": "89",
    "label": "1",
    "explanation": "Dorgan announces a favorable federal decision for his state (Bismarck State College's designation as National Power Plant Operations Technology and Educational Center) and notes he 'authored legislation, which was signed into law, that created the National Center designation.' This combines clarification (1) (announcement of a favorable agency decision for the state) and (3) (enactment of legislation he authored)."
  },
  "240": {
    "document_id": "240",
    "label": "0",
    "explanation": "Ensign's statement on the Chertoff confirmation is a pure position statement expressing support and anticipation of working together. Under negative clarification (1), position statements are not credit-claiming; no benefit is delivered or outcome achieved by Ensign."
  },
  "453": {
    "document_id": "453",
    "label": "0",
    "explanation": "Nelson explains his votes against two Iraq withdrawal resolutions. Under negative clarification (1), a vote explanation is a position statement, not a claim of responsibility for a delivered benefit or achieved outcome."
  },
  "597": {
    "document_id": "597",
    "label": "0",
    "explanation": "Lugar presents a health and fitness award at his annual community run. Under negative clarification (4), award ceremonies and ceremonial content are not credit-claiming; no federal resources or favorable decisions are claimed."
  },
  "656": {
    "document_id": "656",
    "label": "0",
    "explanation": "Kerry's statement on the collapse of the Dubai Ports deal is criticism of the Bush administration's port security failures. Under negative clarification (3), criticism of the administration is not credit-claiming; he claims no causal role in the deal's demise."
  },
  "918": {
    "document_id": "918",
    "label": "0",
    "explanation": "Allard announces a town meeting in Greeley. Under negative clarification (4), town-meeting announcements are ceremonial/advertising content, not credit-claiming."
  },
  "967": {
    "document_id": "967",
    "label": "1",
    "explanation": "Shelby announces that HHS will release $3,305,732 to Talladega-area Head Start programs. Under clarification (1), a senator's announcement that federal funds are coming to their state is an implicit credit claim even without the words 'I secured.'"
  },
  "1021": {
    "document_id": "1021",
    "label": "1",
    "explanation": "Wyden and Smith announce Senate Appropriations Committee approval of funding for Oregon programs (Pacific Coast Salmon Recovery Fund, OSU ocean observation research, and other Oregon initiatives). Under clarification (1), announcing that federal funds have been approved for their state is an implicit credit claim; like the Talent positive example (funding approved but awaiting further steps), the delivered committee approval of state funding suffices."
  },
  "1957": {
    "document_id": "1957",
    "label": "1",
    "explanation": "Dodd and Lieberman announce that Bradley International Airport will receive a $2,250,000 federal grant. Under clarification (1), a senator's announcement of federal grant money coming to their state is an implicit credit claim."
  },
  "2318": {
    "document_id": "2318",
    "label": "1",
    "explanation": "Although the release primarily urges Illinois officials to act, Durbin explicitly claims past achievements: 'I helped secure an expedited environmental review from the federal government and facilitated the return of the project to the national priority list for federal funding.' This matches clarification (2) ('I helped secure,' 'I worked with the agency to expedite') — explicit claims of personal responsibility for favorable federal decisions already obtained. I considered negative clarification (6) on incidental mentions, but the claim is repeated in both the release and the letter and is central to his argument, not a passing background reference."
  },
  "2807": {
    "document_id": "2807",
    "label": "0",
    "explanation": "Lincoln helps recognize Arkansas Women in Agriculture month and applauds a gubernatorial proclamation. Under negative clarification (4), commemorations and ceremonial proclamations are not credit-claiming; her committee role is background, and no benefit is claimed as delivered."
  },
  "3482": {
    "document_id": "3482",
    "label": "1",
    "explanation": "Mikulski and Cardin announce a $294,980 federal SAFER grant awarded to Allegany County firefighters. Under clarification (1), a senator's announcement of federal grant funding coming to their state constituents is an implicit credit claim."
  },
  "3577": {
    "document_id": "3577",
    "label": "0",
    "explanation": "Sarbanes' hearing statement criticizes FEMA's handling of the flood insurance program and calls for reforms. Under negative clarifications (1) and (3), this is a position statement and criticism. His mention of reforms he 'worked with Senator Bunning... to formulate and move through' is incidental background, and he emphasizes FEMA has not implemented them — no achieved outcome is claimed as his own delivered benefit (boundary test and negative clarification (6))."
  },
  "3659": {
    "document_id": "3659",
    "label": "0",
    "explanation": "Clinton 'welcomes' the NIOSH advisory board recommendation and 'urges' the Secretary to act on it. This matches the codebook's negative example exactly: under negative clarification (5), merely welcoming a decision made by others, with no claimed causal role and an outcome not yet final, is not credit-claiming."
  },
  "3687": {
    "document_id": "3687",
    "label": "1",
    "explanation": "Bingaman announces that New Mexico State University has been awarded $599,691 in USDA funding for food safety research. Under clarification (1), a senator's announcement of federal funds coming to their state is an implicit credit claim."
  },
  "4208": {
    "document_id": "4208",
    "label": "0",
    "explanation": "Dorgan and Lott announce they will introduce legislation to halt the FCC's media ownership rule changes. Under negative clarification (2), announcing introduction of a bill is a proposal without an achieved outcome, not credit-claiming."
  },
  "4585": {
    "document_id": "4585",
    "label": "1",
    "explanation": "Schumer announces that two Westchester County fire departments will receive over $134,000 in federal fire grants. Under clarification (1), a senator's announcement of federal grant funding coming to their state is an implicit credit claim, reinforced by the note that he 'has pushed for additional funding' for the program."
  },
  "4771": {
    "document_id": "4771",
    "label": "1",
    "explanation": "Clinton states she 'played a key role... in preventing the removal of four C-130 Aircraft' from Stratton Air National Guard base. This matches the codebook's positive example: an explicit claim of personal responsibility for a favorable government decision (BRAC outcome) benefiting her state, satisfying clarification (2)."
  }
}
